from collections.abc import Callable
from threading import Lock
from typing import TYPE_CHECKING, TypeVar

if TYPE_CHECKING:
    from .session import SessionEvent, SessionLog


_T = TypeVar("_T")


class AgentInterrupted(RuntimeError):
    """A cooperative stop observed at a named agent boundary."""

    def __init__(self, reason: str, phase: str):
        if not isinstance(reason, str) or not reason.strip():
            raise ValueError("interruption reason must not be blank")
        if not isinstance(phase, str) or not phase.strip():
            raise ValueError("interruption phase must not be blank")
        self.reason = reason
        self.phase = phase
        super().__init__(f"agent interrupted during {phase}: {reason}")


class CancellationToken:
    """A thread-safe, first-writer-wins cooperative cancellation signal."""

    def __init__(self):
        self._lock = Lock()
        self._reason: str | None = None

    @property
    def cancelled(self) -> bool:
        with self._lock:
            return self._reason is not None

    @property
    def reason(self) -> str | None:
        with self._lock:
            return self._reason

    def cancel(self, reason: str = "user_interrupt") -> bool:
        """Publish the first cancellation reason and report whether it won."""

        if not isinstance(reason, str) or not reason.strip():
            raise ValueError("cancellation reason must not be blank")
        with self._lock:
            if self._reason is not None:
                return False
            self._reason = reason
            return True

    def raise_if_cancelled(self, phase: str) -> None:
        """Raise with the stable cancellation reason when cancellation won."""

        with self._lock:
            reason = self._reason
        if reason is not None:
            raise AgentInterrupted(reason, phase)

    def run_if_active(self, phase: str, operation: Callable[[], _T]) -> _T:
        """Linearize one terminal operation against cancellation publication."""

        with self._lock:
            if self._reason is not None:
                raise AgentInterrupted(self._reason, phase)
            return operation()


class SteeringHandle:
    """Queue operator steering in the durable session transcript."""

    def __init__(self, session: SessionLog):
        self.session = session

    def submit(self, message: str) -> SessionEvent:
        """Durably queue one non-blank message for the next safe turn boundary."""

        return self.session.queue_steering(message)
